import java.io.*; import java.util.*; import java.util.stream.*; import static java.util.stream.Collectors.toList; class Result { public static int sockMerchant(int n, List<Integer> ar) { Set<Integer> unpaired = new HashSet<>(); int pairs = 0; for (int color : ar) { if (unpaired.contains(color)) { pairs++; unpaired.remove(color); } else { unpaired.add(color); } } return pairs; } } public class Solution { public static void main(String[] args) throws IOException { BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in)); String outputEnv = System.getenv("OUTPUT_PATH"); BufferedWriter bufferedWriter = new BufferedWriter(outputEnv != null ? new FileWriter(outputEnv) : new OutputStreamWriter(System.out)); String line1 = bufferedReader.readLine(); if (line1 != null) { int n = Integer.parseInt(line1.trim()); List<Integer> ar = Stream.of(bufferedReader.readLine().replaceAll("\\s+$", "").split(" ")).map(Integer::parseInt).collect(toList()); int result = Result.sockMerchant(n, ar); bufferedWriter.write(String.valueOf(result)); bufferedWriter.newLine(); } bufferedReader.close(); bufferedWriter.close(); } }